INSERT INTO `course` VALUES
(1,'CP001','静夜思','五言绝句','一年级','file/course1.jpg','李白代表作，描写秋夜望月思乡之情','床前明月光，疑是地上霜。举头望明月，低头思故乡。','file/1.mp4',165,4,1320,'2026-01-15 10:00:00','2026-04-09 19:41:41'),
(2,'CP002','咏鹅','五言古诗','一年级','file/course2.jpg','骆宾王七岁所作，描写鹅的生动形象','鹅，鹅，鹅，曲项向天歌。白毛浮绿水，红掌拨清波。','file/2.mp4',189,2,1450,'2026-01-15 10:00:00','2026-04-09 19:42:00'),
(3,'CP003','春晓','五言绝句','一年级','file/course3.jpg','孟浩然代表作，描写春日早晨的景象','春眠不觉晓，处处闻啼鸟。夜来风雨声，花落知多少。','file/3.mp4',210,5,1680,'2026-01-15 10:00:00','2026-04-09 19:43:00'),
(4,'CP004','登鹳雀楼','五言绝句','一年级','file/course4.jpg','王之涣名篇，写登高望远的壮阔景象','白日依山尽，黄河入海流。欲穷千里目，更上一层楼。','file/4.mp4',178,3,1420,'2026-01-15 10:00:00','2026-04-09 19:44:00'),
(5,'CP005','悯农（其二）','五言古诗','二年级','file/course5.jpg','李绅名篇，教育孩子珍惜粮食','锄禾日当午，汗滴禾下土。谁知盘中餐，粒粒皆辛苦。','file/5.mp4',230,6,1890,'2026-01-20 10:00:00','2026-04-09 19:45:00'),
(6,'CP006','望庐山瀑布','七言绝句','二年级','file/course6.jpg','李白游庐山所作，气势磅礴','日照香炉生紫烟，遥看瀑布挂前川。飞流直下三千尺，疑是银河落九天。','file/6.mp4',195,4,1560,'2026-01-20 10:00:00','2026-04-09 19:46:00'),
(7,'CP007','江雪','五言绝句','二年级','file/course7.jpg','柳宗元代表作，写雪中独钓的孤寂','千山鸟飞绝，万径人踪灭。孤舟蓑笠翁，独钓寒江雪。','file/7.mp4',168,2,1340,'2026-01-20 10:00:00','2026-04-09 19:47:00'),
(8,'CP008','绝句','七言绝句','三年级','file/course8.jpg','杜甫名篇，描写成都草堂的春景','两个黄鹂鸣翠柳，一行白鹭上青天。窗含西岭千秋雪，门泊东吴万里船。','file/8.mp4',187,3,1510,'2026-01-25 10:00:00','2026-04-09 19:48:00'),
(9,'CP009','元日','七言绝句','三年级','file/course9.jpg','王安石名篇，描写新年元日的热闹','爆竹声中一岁除，春风送暖入屠苏。千门万户曈曈日，总把新桃换旧符。','file/9.mp4',172,2,1380,'2026-01-25 10:00:00','2026-04-09 19:49:00'),
(10,'CP010','清明','七言绝句','三年级','file/course10.jpg','杜牧名篇，写清明时节的哀思','清明时节雨纷纷，路上行人欲断魂。借问酒家何处有？牧童遥指杏花村。','file/10.mp4',201,5,1620,'2026-01-25 10:00:00','2026-04-09 19:50:00'),
(11,'CP011','题西林壁','七言绝句','四年级','file/course11.jpg','苏轼游庐山题壁，蕴含深刻哲理','横看成岭侧成峰，远近高低各不同。不识庐山真面目，只缘身在此山中。','file/11.mp4',220,4,1760,'2026-02-01 10:00:00','2026-04-09 19:51:00'),
(12,'CP012','游子吟','五言古诗','四年级','file/course12.jpg','孟郊名篇，歌颂母爱的伟大','慈母手中线，游子身上衣。临行密密缝，意恐迟迟归。谁言寸草心，报得三春晖。','file/12.mp4',245,3,1980,'2026-02-01 10:00:00','2026-04-09 19:52:00'),
(13,'CP013','出塞','七言绝句','四年级','file/course13.jpg','王昌龄边塞诗代表作','秦时明月汉时关，万里长征人未还。但使龙城飞将在，不教胡马度阴山。','file/13.mp4',193,2,1550,'2026-02-01 10:00:00','2026-04-09 19:53:00'),
(14,'CP014','示儿','七言绝句','五年级','file/course14.jpg','陆游临终绝笔，表达爱国情怀','死去元知万事空，但悲不见九州同。王师北定中原日，家祭无忘告乃翁。','file/14.mp4',210,4,1690,'2026-02-10 10:00:00','2026-04-09 19:54:00'),
(15,'CP015','枫桥夜泊','七言绝句','五年级','file/course15.jpg','张继名篇，写苏州枫桥夜景','月落乌啼霜满天，江枫渔火对愁眠。姑苏城外寒山寺，夜半钟声到客船。','file/15.mp4',188,3,1520,'2026-02-10 10:00:00','2026-04-09 19:55:00'),
(16,'CP016','长相思','词','五年级','file/course16.jpg','纳兰性德词作，写羁旅思乡之情','山一程，水一程，身向榆关那畔行，夜深千帐灯。风一更，雪一更，聒碎乡心梦不成，故园无此声。','file/16.mp4',176,2,1410,'2026-02-10 10:00:00','2026-04-09 19:56:00'),
(17,'CP017','长歌行','乐府诗','六年级','file/course17.jpg','汉乐府名篇，劝人珍惜时光','青青园中葵，朝露待日晞。阳春布德泽，万物生光辉。常恐秋节至，焜黄华叶衰。百川东到海，何时复西归？少壮不努力，老大徒伤悲！','file/17.mp4',260,5,2100,'2026-02-15 10:00:00','2026-04-09 19:57:00'),
(18,'CP018','石灰吟','七言绝句','六年级','file/course18.jpg','于谦托物言志，表达坚贞品格','千锤万凿出深山，烈火焚烧若等闲。粉骨碎身浑不怕，要留清白在人间。','file/18.mp4',230,3,1850,'2026-02-15 10:00:00','2026-04-09 19:58:00'),
(19,'CP019','竹石','七言绝句','六年级','file/course19.jpg','郑燮题画诗，赞美竹的坚韧','咬定青山不放松，立根原在破岩中。千磨万击还坚劲，任尔东西南北风。','file/19.mp4',205,2,1640,'2026-02-15 10:00:00','2026-04-09 19:59:00');
